referenceSolutions.javascript:
export function randomPickWithWeight(weights          , tickets          )           {
const sums         =[];let sum=0;for(const w of weights){sum+=w;sums.push(sum);}return tickets.map(t=>{let l=0,r=sums.length-1;while(l<r){const m=(l+r)>>1;if(sums[m]>t)r=m;else l=m+1;}return l;});
}

